parameters.jsCode:
// CATEGORY + FORMAT ROTATION + "OVERUSED TECHNOLOGIES" BLACKLIST
// The workflow runs weekly, so rotation is driven by the week of the year.
// (A day-of-year index that advances by 7 per run would only ever visit 2 of 14 categories.)
const C = $('Config').first().json;
// "Fetch Last 50 Posts" has alwaysOutputData on, so a brand-new blog yields one empty item.
const posts = $input.all().filter(p => p.json && p.json.title);
const clean = s => String(s || '').replace(/<[^>]+>/g, '');

const allTitles = posts.map(p => `- ${clean(p.json.title.rendered)}`).join('\n');

// Technologies that dominated the last N days of titles -> the topic prompt must not make them the main topic.
const windowDays = Number(C.overused_window_days) || 14;
const now = Date.now();
const recentPosts = posts.filter(p => {
  const t = Date.parse(p.json.date || p.json.date_gmt || '');
  return !isNaN(t) && (now - t) <= windowDays * 24 * 60 * 60 * 1000;
});
const techRegex = /\b([A-Z][a-zA-Z]*(?:\d+(?:\.\d+)?)?|[A-Z]{2,}(?:\d+(?:\.\d+)?)?)\b/g;
const stopWords = new Set([
  // generic acronyms
  'I','II','III','IV','API','SQL','HTTP','URL','JSON','XML','YAML','CSS','HTML','JS','TS','UI','UX','OS','PR','DB','CI','CD','EU','US',
  // common English title words (Title Case would otherwise flood the list)
  'THE','AND','FOR','WITH','HOW','WHAT','WHEN','WHY','WHO','WHICH','WHERE','YOUR','YOU','ARE','CAN','USE','USING','GUIDE','FROM',
  'INTO','THAT','THIS','BEST','PRACTICES','PATTERNS','STEP','BUILD','BUILDING','COMMON','MISTAKES','TUTORIAL','EXAMPLE','EXAMPLES',
  'WITHOUT','BETWEEN','SHOULD','NOT','ITS','OUR','ALL','NEW','GET','MAKE','VERSUS','EXPLAINED','INTRODUCTION','COMPLETE',
  'PRACTICAL','DECISION','FRAMEWORK','CHOOSE','CHOOSING','OVER','ABOUT','DOES','WORK','WORKS','FIX','FIXING','PITFALLS','CASE',
  'STUDY','MIGRATION','MIGRATING','SCRATCH','ONE','TWO','THREE','FOUR','FIVE','WAYS','TIPS','VIA','AFTER','BEFORE',
  'MORE','LESS','THAN'
]);
const techFreq = {};
for (const p of recentPosts) {
  const matches = clean(p.json.title.rendered).match(techRegex) || [];
  for (const m of matches) {
    if (m.length < 3) continue;
    if (stopWords.has(m.toUpperCase())) continue;
    techFreq[m] = (techFreq[m] || 0) + 1;
  }
}
const overusedTechnologies = Object.entries(techFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 15)
  .map(([k]) => k)
  .join(', ') || `(no notable repetition in the last ${windowDays} days)`;

const categories = Array.isArray(C.categories) ? C.categories : [];
const formats = Array.isArray(C.formats) ? C.formats : [];
if (!categories.length) throw new Error('Config.categories is empty');
if (!formats.length) throw new Error('Config.formats is empty');

// Week-of-year rotation ($now respects the workflow / GENERIC_TIMEZONE setting)
const dayOfYear = $now.ordinal;
const weekIdx = Math.floor(dayOfYear / 7);
const sel = categories[weekIdx % categories.length];
const fmt = formats[weekIdx % formats.length];

// Internal link candidates: WordPress link -> public URL (headless frontends)
const wpBase = String(C.wp_site_url || '').replace(/\/+$/, '');
const pubBase = String(C.public_url_base || '').replace(/\/+$/, '');
const toPublic = link => (wpBase && pubBase && link.indexOf(wpBase) === 0) ? pubBase + link.substring(wpBase.length) : link;
const internalLinks = posts.slice(0, 40).map(p => `- ${clean(p.json.title.rendered)} → ${toPublic(p.json.link || '')}`).join('\n');

return [{
  json: {
    all_titles: allTitles || '(no posts yet)',
    overused_technologies: overusedTechnologies,
    overused_window_days: windowDays,
    category_code: sel.code,
    category_name: sel.name,
    category_topics: sel.topics,
    format_code: fmt.code,
    format_name: fmt.name,
    format_description: fmt.description,
    format_guide: fmt.guide,
    all_formats: formats,
    existing_titles: posts.map(p => clean(p.json.title.rendered)),
    internal_links: internalLinks || '(no posts yet)',
    day_of_year: dayOfYear,
    post_count: posts.length
  }
}];

// This week's real trend signals: Hacker News, dev.to, GitHub, Reddit.
// Every source is optional (Config.trend_sources) and fails silently: a blocked source never stops the run.
const C = $('Config').first().json;
const T = C.trend_sources || {};
const UA = C.http_user_agent || 'Mozilla/5.0 (compatible; n8n-blog-bot/1.0)';
const get = async (url, headers = {}) => {
  try {
    const r = await this.helpers.httpRequest({ url, headers: { 'User-Agent': UA, ...headers }, timeout: 15000 });
    return typeof r === 'string' ? JSON.parse(r) : r;
  } catch (e) { return null; }
};
const out = [];
const weekAgo = Math.floor(Date.now() / 1000) - 7 * 86400;

if (T.hackernews?.enabled !== false) {
  const minPoints = Number(T.hackernews?.min_points) || 150;
  const hn = await get('https://hn.algolia.com/api/v1/search?tags=story&hitsPerPage=30&numericFilters=' + encodeURIComponent(`created_at_i>${weekAgo},points>${minPoints}`));
  for (const h of (hn?.hits || [])) out.push(`[HN ${h.points}p] ${h.title}`);
}

if (T.devto?.enabled !== false) {
  const tag = String(T.devto?.tag || '').trim();
  const dev = await get('https://dev.to/api/articles?top=7&per_page=25' + (tag ? '&tag=' + encodeURIComponent(tag) : ''));
  for (const a of (Array.isArray(dev) ? dev : [])) out.push(`[dev.to ${a.public_reactions_count}♥] ${a.title} (${(a.tag_list || []).map(t => '#' + t).join(' ')})`);
}

if (T.github?.enabled !== false) {
  const since = new Date(Date.now() - 14 * 86400000).toISOString().slice(0, 10);
  const extra = String(T.github?.extra_query || '').trim();
  const q = `created:>${since}` + (extra ? ' ' + extra : '');
  const gh = await get(`https://api.github.com/search/repositories?q=${encodeURIComponent(q)}&sort=stars&order=desc&per_page=15`, { Accept: 'application/vnd.github+json' });
  for (const r of (gh?.items || [])) out.push(`[GitHub ★${r.stargazers_count}] ${r.full_name}: ${(r.description || '').slice(0, 120)}`);
}

if (T.reddit?.enabled !== false) {
  const subs = Array.isArray(T.reddit?.subreddits) && T.reddit.subreddits.length ? T.reddit.subreddits : ['programming'];
  for (const sub of subs) {
    const rd = await get(`https://www.reddit.com/r/${encodeURIComponent(sub)}/top.json?t=week&limit=20`);
    for (const c of (rd?.data?.children || [])) out.push(`[r/${sub} ${c.data.score}] ${c.data.title}`);
  }
}

return [{ json: { trend_signals: out.join('\n') || '(no trend data could be fetched — check with Google Search yourself)', trend_count: out.length } }];

// Builds the prompt for the Google-Search-grounded topic brainstorm (6 candidates).
const C = $('Config').first().json;
const r = $('Category + Format Rotation').first().json;
const trend = $json.trend_signals;
const today = $now.toFormat('yyyy-MM-dd');
const lang = C.language || 'English';
const audience = C.audience || 'software developers';
const formatList = r.all_formats.map(f => `- ${f.name}: ${f.description}`).join('\n');
const examples = (C.keyword_examples || []).map(e => `"${e}"`).join(', ');

const prompt = `You are the content strategist of a technical blog for ${audience}. The blog is written in ${lang}. Today's date: ${today}.
Goal: find topics with high organic-search and sharing potential that are CURRENT and that people ACTUALLY SEARCH FOR.

Use the Google Search tool to check: important releases and announcements from the last 2-4 weeks, what ${audience} are discussing most right now, and questions people search for where good ${lang}-language resources are scarce. If your knowledge is outdated, update it with search; never present old versions or old product names as current.

THIS WEEK'S TREND SIGNALS (Hacker News, dev.to, GitHub, Reddit)
${trend}

THIS WEEK'S FOCUS CATEGORY: ${r.category_name}
Subtopics: ${r.category_topics}

THIS WEEK'S SUGGESTED FORMAT: ${r.format_name}

AVAILABLE FORMATS
${formatList}

TECHNOLOGIES COVERED A LOT IN THE LAST ${r.overused_window_days} DAYS (do not make them the main topic): ${r.overused_technologies}

EXISTING POSTS (do not repeat the same topic or a very similar angle)
${r.all_titles}

TASK: produce 6 candidate topics.
- 3 candidates from the focus category, 3 candidates from the trend signals (any area relevant to ${audience}).
- Each candidate must either (a) be based on a concrete development that is in the news right now (new release, new tool, important change, debate) or (b) answer an evergreen question with consistently high search volume.
- Micro-niche topics that only a handful of experts care about are FORBIDDEN. It must be a need that an intermediate reader would type into Google.
- focus_keyword: a 2-4 word search phrase that a reader would REALLY type into Google, in ${lang}, lowercase. Technical terms may stay in English. Examples: ${examples}.
- title: 45-70 characters, in ${lang}. The focus_keyword appears in the first half of the title and the title promises a clear benefit.
- Invented numeric results in the title ("80% faster", "from 800ms to 120ms") are FORBIDDEN. Empty adjectives such as "modern, powerful, fast, efficient, revolutionary, ultimate" are FORBIDDEN.
- A bare "What is X?" title is not allowed, but concrete angles such as "What Is X and When Should You Use It? A Guide with Examples" are fine.

OUTPUT: return only a JSON array. No explanation, markdown or code fence before or after it.
[{"title":"...","focus_keyword":"...","secondary_keywords":["...","...","..."],"format":"<one of the format names above, verbatim>","trend_score":1,"why_now":"one sentence: concrete development or evergreen need","target_reader":"...","category":"..."}]
trend_score is an integer 1-5: 5 = a new development everyone is talking about right now, 1 = timeless topic.`;

return [{ json: { prompt, temperature: 0.9 } }];

// Parse the topic candidates, measure REAL search demand with Google Autocomplete, pick the best one,
// and build the prompt for the grounded research brief.
const C = $('Config').first().json;
const raw = $input.first().json;
const txt = (raw?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('\n');
const m = txt.match(/\[[\s\S]*\]/);
let arr;
try { arr = JSON.parse(m[0]); } catch (e) { throw new Error('Could not parse topic candidates: ' + txt.slice(0, 500)); }
arr = (Array.isArray(arr) ? arr : []).filter(c => c && c.title && c.focus_keyword).slice(0, 8);
if (!arr.length) throw new Error('No valid topic candidates: ' + txt.slice(0, 500));

const r = $('Category + Format Rotation').first().json;
const locale = C.locale || 'en-US';
const lang = C.language || 'English';
const hl = encodeURIComponent(C.autocomplete_hl || 'en');
const gl = encodeURIComponent(C.autocomplete_gl || 'us');
const lc = s => String(s || '').toLocaleLowerCase(locale);
// Unicode-aware tokenizer (works for English, Turkish, German, ...). HTML entities for quotes are normalized first.
const toks = s => lc(s).replace(/&#8217;|&#8216;|’|‘/g, "'").replace(/<[^>]+>/g, '').replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(w => w.length > 2);
const existing = (r.existing_titles || []).map(t => new Set(toks(t)));
const overlap = (a, b) => { let i = 0; for (const x of a) if (b.has(x)) i++; return i / Math.max(1, Math.min(a.size, b.size)); };

// Google Autocomplete (unofficial endpoint). null = request failed, [] = no suggestions.
const ac = async q => {
  try {
    const res = await this.helpers.httpRequest({ url: `https://suggestqueries.google.com/complete/search?client=firefox&hl=${hl}&gl=${gl}&q=` + encodeURIComponent(q), headers: { 'User-Agent': 'Mozilla/5.0' }, timeout: 10000 });
    const j = typeof res === 'string' ? JSON.parse(res) : res;
    return Array.isArray(j?.[1]) ? j[1] : [];
  } catch (e) { return null; }
};

for (const c of arr) {
  const kw = lc(c.focus_keyword).trim();
  const kwToks = toks(kw);
  const head = kw.split(/\s+/).slice(0, kw.split(/\s+/).length > 2 ? 2 : 1).join(' ');
  const s1 = await ac(kw);          // does Google complete the full keyword?
  const s2 = await ac(head + ' ');  // how broad is the demand around its head term?
  const hits = s1 ? s1.filter(s => kwToks.every(t => lc(s).includes(t))).length : 0;
  const exact = s1 ? s1.some(s => lc(s).startsWith(kw)) : false;
  const breadth = s2 ? s2.length : 0;
  const tSet = new Set(toks(c.title));
  const maxOverlap = existing.length ? Math.max(...existing.map(e => overlap(tSet, e))) : 0;
  let score = (exact ? 4 : 0) + hits + breadth * 0.3 + (Number(c.trend_score) || 0) * 1.2;
  if (maxOverlap >= 0.6) score -= 20;  // too close to an existing post
  c._demand = { exact, hits, breadth, maxOverlap: +maxOverlap.toFixed(2), score: +score.toFixed(2), suggestions: (s1 || []).slice(0, 5) };
}
arr.sort((a, b) => b._demand.score - a._demand.score);
const sel = arr[0];
const fmt = r.all_formats.find(f => lc(f.name) === lc(sel.format)) || r.all_formats.find(f => f.code === r.format_code);

const today = $now.toFormat('yyyy-MM-dd');
const prompt = `You are a senior technical researcher. Today's date: ${today}. Use Google Search to do CURRENT research for the blog post below and prepare a research brief for the writer.

TOPIC: ${sel.title}
FOCUS KEYWORD: ${sel.focus_keyword}
SECONDARY KEYWORDS: ${(sel.secondary_keywords || []).join(', ')}
FORMAT: ${fmt.name}
WHY NOW: ${sel.why_now || '-'}
TARGET READER: ${sel.target_reader || 'intermediate to senior ' + (C.audience || 'software developers')}

The brief must contain these sections (write it in ${lang}, as bullet points, only verifiable information):
1. CURRENT STATE: current stable versions of the relevant tools/libraries/services and their release dates, recent important changes (with dates). Deprecated APIs.
2. ACCURATE TECHNICAL DETAILS: API/function names, commands, config keys and default values based on the official documentation.
3. READER QUESTIONS: at least 6 questions that someone searching for this keyword wants answered ("People also ask" style).
4. COMPETITOR ANALYSIS: the subtopics covered by the top-ranking content on this topic and the angles they MISS (our opportunity to stand out).
5. PITFALLS: common mistakes, limitations, trade-offs, when NOT to use it.
6. DATA: verified numeric data found in the sources (with the source name). Do not write any number you are not sure about.
7. OFFICIAL SOURCES: URLs of the official documentation and project pages (only permanent, official addresses).

Length: 700-1100 words. No introduction, conclusion or commentary; only the brief.`;

const candidatesSummary = arr.map((c, i) => `${i === 0 ? '✅' : '•'} [${c._demand.score}] ${c.title} — "${c.focus_keyword}" (suggestions: ${c._demand.hits}, exact match: ${c._demand.exact ? 'yes' : 'no'}, trend: ${c.trend_score}, overlap: ${c._demand.maxOverlap})`).join('\n');

return [{ json: {
  title: sel.title,
  focus_keyword: sel.focus_keyword,
  secondary_keywords: sel.secondary_keywords || [],
  why_now: sel.why_now || '',
  target_reader: sel.target_reader || '',
  format_name: fmt.name,
  format_guide: fmt.guide,
  demand: sel._demand,
  candidates_summary: candidatesSummary,
  prompt,
  temperature: 0.3
} }];

// Pull the research brief text + grounding sources out of the Gemini response.
const raw = $input.first().json;
const cand = raw?.candidates?.[0] || {};
const brief = (cand.content?.parts || []).map(p => p.text || '').join('\n').trim();
if (brief.length < 800) throw new Error('Research brief too short or empty: ' + JSON.stringify(raw).slice(0, 500));
const gm = cand.groundingMetadata || {};
const sources = [...new Set((gm.groundingChunks || []).map(c => c.web?.title).filter(Boolean))];
return [{ json: { brief, source_domains: sources, search_queries: gm.webSearchQueries || [] } }];

