// Extract base64 + mime type from the Gemini image response (kept as a string until publishing).
const item = $input.first().json;
const parts = item?.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(part => part?.inlineData?.data);
if (!imagePart) {
  throw new Error('No image found in the Gemini response: ' + JSON.stringify(item).slice(0, 500));
}
const base64 = imagePart.inlineData.data;
const mimeType = imagePart.inlineData.mimeType || 'image/png';
let extension = mimeType.split('/')[1] || 'png';
if (extension === 'jpeg') extension = 'jpg';

return [{
  json: {
    image_base64: base64,
    image_mime: mimeType,
    image_ext: extension,
    image_size_bytes: Buffer.from(base64, 'base64').length
  }
}];

// NUMBER CHECK
// Finds numeric claims in the draft (percentages, durations, multipliers, thousands-formatted numbers)
// whose digits do NOT appear anywhere in the research brief. The editor gets this list and must
// remove them or rephrase them qualitatively. Code blocks are ignored.
// Units cover English and Turkish: 40% / %40, 120 ms / milliseconds / milisaniye, seconds / saniye,
// 3x / 3 times / 3 kat, percent, 10,000 / 10.000. Extend the regex for other languages.
const brief = String($('Extract Brief').first().json.brief || '');
const txt = String($json.text || '');
const digits = n => String(n).replace(/[^\d]/g, '');
const briefDigits = new Set((brief.match(/\d+(?:[.,]\d+)*/g) || []).map(digits));
const body = txt.replace(/<pre[\s\S]*?<\/pre>/gi, ' ').replace(/<code[\s\S]*?<\/code>/gi, ' ');
const re = /%\s?\d+(?:[.,]\d+)?|\d+(?:[.,]\d+)?\s?%|\d+(?:[.,]\d+)?\s?(?:ms|milliseconds?|milisaniye|seconds?|saniye|percent|per\s?cent|times|kat|x)\b|(?<![\d.])\d{1,3}(?:\.\d{3})+(?![\d.]*\d)|(?<![\d,])\d{1,3}(?:,\d{3})+(?![\d,]*\d)/gi;
const unsourced = [...new Set((body.match(re) || []).filter(m => !briefDigits.has(digits(m.match(/\d+(?:[.,]\d+)*/)[0]))))];
return [{ json: { text: txt, unsourced_numbers: unsourced } }];

