parameters.jsCode:
// QUALITY GATE
// 1) Try the editor's version. 2) If it fails any check, fall back to the original draft.
// 3) If neither passes, stop the run with a clear error — nothing gets published.
const C = $('Config').first().json;
const locale = C.locale || 'en-US';
const minWords = Number(C.gate_min_words) || 1200;

const parse = (txt) => {
  let r = String(txt || '').replace(/^\s*```(?:json)?\s*|\s*```\s*$/gi, '').trim();
  const a = r.indexOf('{'), b = r.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(r.slice(a, b + 1)); } catch (e) { return null; }
};

// Same logic as "Number Check": numbers in the final text must exist in the research brief.
const brief = String($('Extract Brief').first().json.brief || '');
const digits = n => String(n).replace(/[^\d]/g, '');
const briefDigits = new Set((brief.match(/\d+(?:[.,]\d+)*/g) || []).map(digits));
const unsourced = (html) => {
  const body = html.replace(/<pre[\s\S]*?<\/pre>/gi, ' ').replace(/<code[\s\S]*?<\/code>/gi, ' ');
  const re = /%\s?\d+(?:[.,]\d+)?|\d+(?:[.,]\d+)?\s?%|\d+(?:[.,]\d+)?\s?(?:ms|milliseconds?|milisaniye|seconds?|saniye|percent|per\s?cent|times|kat|x)\b|(?<![\d.])\d{1,3}(?:\.\d{3})+(?![\d.]*\d)|(?<![\d,])\d{1,3}(?:,\d{3})+(?![\d,]*\d)/gi;
  return [...new Set((body.match(re) || []).filter(m => !briefDigits.has(digits(m.match(/\d+(?:[.,]\d+)*/)[0]))))];
};

const escRe = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const fakeList = (C.fake_experience_patterns || []).filter(Boolean).map(escRe);
const fakeRe = fakeList.length ? new RegExp(fakeList.join('|'), 'i') : null;

const check = (x) => {
  const t = String(x.title || '').trim(), e = String(x.excerpt || '').trim(), h = String(x.content || '').trim();
  const words = h.replace(/<pre[\s\S]*?<\/pre>/gi, ' ').replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
  if (t.length < 30 || t.length > 95) return 'title length ' + t.length;
  if (e.length < 110 || e.length > 200) return 'excerpt length ' + e.length;
  if (words < minWords) return 'content too short (' + words + ' words)';
  if (/parse\s*(?:error|hatası)|title could not be (?:set|generated)|başlık atanamadı|content is empty|içerik boş/i.test(t + ' ' + e + ' ' + h)) return 'fallback text';
  if (C.require_code_example !== false && !/<pre><code\b/i.test(h)) return 'no code example';
  if ((h.match(/<h2\b/gi) || []).length < 4) return 'too few h2 sections';
  if (/<(script|style|iframe|form|object|embed)\b/i.test(h)) return 'unsafe HTML';
  if (fakeRe && fakeRe.test(h)) return 'invented personal experience';
  const ks = unsourced(h + ' ' + t);
  if (ks.length) return 'unsourced numeric claim: ' + ks.slice(0, 5).join(', ');
  if (/\d+\s*ms(?:'?(?:den|dan)|\s*(?:to|→|->))\s*\d+\s*ms/i.test(t)) return 'invented metric in title';
  return '';
};

const sel = $('Pick Topic').first().json;
const candidates = [['editor', parse($('Editor Revision').first().json.text)], ['draft', parse($('Generate Content').first().json.text)]];
let chosen = null, source = '';
const errors = [];
for (const [name, x] of candidates) {
  if (!x) { errors.push(name + ': could not parse JSON'); continue; }
  const err = check(x);
  if (!err) { chosen = x; source = name; break; }
  errors.push(name + ': ' + err);
}
if (!chosen) throw new Error('Quality gate: ' + errors.join(' | '));

const h = String(chosen.content).trim().replace(/<\/?h1\b[^>]*>/gi, '');
const kw = String(sel.focus_keyword || '').toLocaleLowerCase(locale);
const warnings = [...errors];
if (kw && !String(chosen.title).toLocaleLowerCase(locale).includes(kw)) warnings.push('focus keyword not verbatim in title');
const linkBase = String(C.public_url_base || C.wp_site_url || '').replace(/\/+$/, '').toLowerCase();
const internalLinkCount = linkBase ? h.toLowerCase().split('href="' + linkBase).length - 1 : 0;
if (internalLinkCount === 0) warnings.push('no internal links');
const wordCount = h.replace(/<pre[\s\S]*?<\/pre>/gi, ' ').replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;

// Short, ASCII, keyword-based slug. Used only if it has at least 8 characters; otherwise WordPress derives one from the title.
const charMap = { 'ç': 'c', 'ğ': 'g', 'ı': 'i', 'ö': 'o', 'ş': 's', 'ü': 'u', 'â': 'a', 'î': 'i', 'û': 'u', 'ß': 'ss', 'æ': 'ae', 'ø': 'o', 'đ': 'd', 'ł': 'l' };
const slugify = s => String(s || '').toLocaleLowerCase(locale).replace(/[çğıöşüâîûßæøđł]/g, ch => charMap[ch])
  .normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  .split('-').filter(Boolean).slice(0, 7).join('-');
const slug = slugify(chosen.slug || sel.focus_keyword || '');

return [{ json: {
  title: String(chosen.title).trim(),
  excerpt: String(chosen.excerpt).trim(),
  content: h,
  slug: slug.length >= 8 ? slug : '',
  tags: Array.isArray(chosen.tags) ? chosen.tags.map(String).slice(0, 5) : [],
  status: C.post_status || 'publish',
  focus_keyword: sel.focus_keyword,
  source,
  word_count: wordCount,
  internal_link_count: internalLinkCount,
  warnings,
  quality_gate: 'passed'
} }];

// Hand the cover image (generated earlier in the run) to "Cover Image to File", with an SEO-friendly file name.
const img = $('Extract Image Base64').first().json;
const q = $('Quality Gate').first().json;
const base = q.slug || 'cover';
return [{ json: {
  image_base64: img.image_base64,
  image_mime: img.image_mime,
  image_filename: `${base}-${Date.now()}.${img.image_ext || 'png'}`,
  alt_text: q.title
} }];

// One item per tag -> "Get or Create Tag" resolves each name to a WordPress tag ID.
// Falls back to the focus keyword so there is always at least one item.
const q = $('Quality Gate').first().json;
const seen = new Set();
const names = [];
for (const t of (q.tags || [])) {
  const name = String(t).trim().slice(0, 40);
  const key = name.toLowerCase();
  if (name && !seen.has(key)) { seen.add(key); names.push(name); }
}
if (!names.length && q.focus_keyword) names.push(String(q.focus_keyword).trim().slice(0, 40));
return names.map(name => ({ json: { name } }));

// Collect tag IDs + featured image ID and build the WordPress post body.
// Tag or image problems never block publishing; they show up as warnings in the report mail.
const C = $('Config').first().json;
const q = $('Quality Gate').first().json;
const warnings = [...(q.warnings || [])];

const tagIds = [];
for (const it of $('Get or Create Tag').all()) {
  const j = it.json || {};
  // New tag -> { id }. Existing tag -> WordPress answers 400 "term_exists" with data.term_id.
  const id = Number(j.id) || Number(j.data?.term_id) || 0;
  if (id && !tagIds.includes(id)) tagIds.push(id);
}
if (!tagIds.length) warnings.push('tags could not be created or resolved');

const media = $('Upload Featured Image').first().json || {};
const mediaId = Number(media.id) || 0;
if (!mediaId) warnings.push('featured image upload failed: ' + JSON.stringify(media.error || media).slice(0, 300));

const payload = { title: q.title, content: q.content, excerpt: q.excerpt, status: q.status };
if (mediaId) payload.featured_media = mediaId;
if (q.slug) payload.slug = q.slug;
if (tagIds.length) payload.tags = tagIds;
const cats = (Array.isArray(C.wp_category_ids) ? C.wp_category_ids : []).map(Number).filter(n => n > 0);
if (cats.length) payload.categories = cats;

return [{ json: { payload, tag_ids: tagIds, media_id: mediaId, media_url: media.source_url || '', warnings } }];

// WordPress link -> public URL (differs on headless setups). Google Indexing API and IndexNow use the public URL.
const C = $('Config').first().json;
const post = $('Create Post').first().json;
const rawUrl = post.link || '';
const wpBase = String(C.wp_site_url || '').replace(/\/+$/, '');
const pubBase = String(C.public_url_base || '').replace(/\/+$/, '');
let publicUrl = rawUrl;
if (rawUrl && wpBase && pubBase && rawUrl.indexOf(wpBase) === 0) {
  publicUrl = pubBase + rawUrl.substring(wpBase.length);
}
const host = (publicUrl.match(/^https?:\/\/([^/?#]+)/i) || [])[1] || '';
const key = String(C.indexnow_key || '').trim();
const keyLocation = String(C.indexnow_key_location || '').trim() || (host && key ? `https://${host}/${key}.txt` : '');

return [{ json: {
  public_url: publicUrl,
  raw_wp_url: rawUrl,
  post_id: post.id,
  post_status: post.status,
  slug: post.slug,
  is_public: post.status === 'publish',
  indexnow_host: host,
  indexnow_key_location: keyLocation
} }];

