// Build the success mail (subject + HTML). Optional steps that did not run are reported as "skipped".
const q = $('Quality Gate').first().json;
const t = $('Pick Topic').first().json;
const b = $('Extract Brief').first().json;
const p = $('Build Post Payload').first().json;
const u = $('Compute Public URL').first().json;
// Optional nodes may not have run in this execution: referencing them must never break the report.
const ran = (name) => {
  try {
    if ($(name).isExecuted === false) return null;
    return $(name).first()?.json || null;
  } catch (e) { return null; }
};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const errText = (j) => typeof j.error === 'string' ? j.error : (j.error?.message || JSON.stringify(j.error || j.body || '').slice(0, 200));
const status = (j, okCodes) => {
  if (!j) return 'skipped (disabled or post not public)';
  if (j.error) return '❌ FAIL — ' + esc(errText(j));
  return okCodes(j.statusCode) ? `✅ OK (HTTP ${j.statusCode})` : `❌ FAIL — HTTP ${j.statusCode} ${esc(JSON.stringify(j.body || '').slice(0, 200))}`;
};
const ok2xx = c => c >= 200 && c < 300;
const deploy = ran('Trigger Deploy Hook');

const html = `<h2>${esc(q.title)}</h2>
<p><strong>Post URL:</strong> <a href="${esc(u.public_url)}">${esc(u.public_url)}</a> (status: ${esc(u.post_status)})</p>
<p><strong>Focus keyword:</strong> ${esc(t.focus_keyword)} — demand score ${t.demand.score}</p>
<p><strong>Why now:</strong> ${esc(t.why_now)}</p>
<p><strong>Format:</strong> ${esc(t.format_name)} · <strong>Words:</strong> ${q.word_count} · <strong>Internal links:</strong> ${q.internal_link_count} · <strong>Text source:</strong> ${esc(q.source)}</p>
<p><strong>Excerpt:</strong> ${esc(q.excerpt)}</p>
<p><strong>Slug / tags:</strong> ${esc(u.slug)} · ${p.tag_ids.length} tag(s) · featured image: ${p.media_id ? '✅' : '❌'}</p>
<p><strong>Warnings:</strong> ${esc(p.warnings.join(' | ') || 'none')}</p>
<p><strong>Research sources:</strong> ${esc((b.source_domains || []).join(', '))}</p>
<h3>Topic candidates</h3>
<pre>${esc(t.candidates_summary)}</pre>
<hr>
<h3>Indexing</h3>
<p><strong>Deploy hook:</strong> ${deploy ? (deploy.error ? '❌ FAIL — ' + esc(errText(deploy)) : '✅ triggered') : 'skipped'}</p>
<p><strong>Google Indexing API:</strong> ${status(ran('Google Indexing API'), ok2xx)}</p>
<p><strong>IndexNow:</strong> ${status(ran('IndexNow'), c => c === 200 || c === 202)}</p>`;

return [{ json: { subject: 'Post published: ' + q.title, html } }];
